import { test, expect } from '@playwright/test';

test.describe('Form Submission Success Feedback', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/form');
  });

  test('should display success feedback after valid form submission', async ({ page }) => {
    // Locate and fill name input using getByLabel
    const nameInput = page.getByLabel('Full Name');
    await nameInput.fill('John Doe');

    // Locate and fill email input using getByLabel
    const emailInput = page.getByLabel('Email Address');
    await emailInput.fill('john.doe@example.com');

    // Locate and fill message textarea using getByLabel
    const messageInput = page.getByLabel('Message');
    await messageInput.fill('This is a test message.');

    // Locate and click submit button using getByRole
    const submitButton = page.getByRole('button', { name: /submit/i });
    await submitButton.click();

    // Wait for success message to appear
    const successMessage = page.getByText(/form submitted successfully/i);
    await expect(successMessage).toBeVisible();

    // Verify success message has correct styling
    await expect(successMessage).toHaveClass(/success-message/);

    // Verify form fields are cleared
    await expect(nameInput).toHaveValue('');
    await expect(emailInput).toHaveValue('');
    await expect(messageInput).toHaveValue('');

    // Verify success icon is visible
    const successIcon = page.getByRole('img', { name: /success/i });
    await expect(successIcon).toBeVisible();
  });

  test('should not display success feedback when form is invalid', async ({ page }) => {
    // Locate and fill name input with invalid data
    const nameInput = page.getByLabel('Full Name');
    await nameInput.fill('John');

    // Locate and fill email input with invalid format
    const emailInput = page.getByLabel('Email Address');
    await emailInput.fill('invalid-email');

    // Locate and fill message textarea with empty value
    const messageInput = page.getByLabel('Message');
    await messageInput.fill('');

    // Locate and click submit button using getByRole
    const submitButton = page.getByRole('button', { name: /submit/i });
    await submitButton.click();

    // Wait for error message to appear
    const errorMessage = page.getByText(/please correct the errors/i);
    await expect(errorMessage).toBeVisible();

    // Verify success message does not appear
    const successMessage = page.getByText(/form submitted successfully/i);
    await expect(successMessage).not.toBeVisible();

    // Verify error message has correct styling
    await expect(errorMessage).toHaveClass(/error-message/);

    // Verify form fields still contain invalid data
    await expect(nameInput).toHaveValue('John');
    await expect(emailInput).toHaveValue('invalid-email');
    await expect(messageInput).toHaveValue('');
  });
});
